import express, { Express } from 'express';
import { ProjectController } from '../controllers/ProjectController';
import { TaskController } from '../controllers/TaskController';
import { UserController } from '../controllers/UserController';
import { errorHandler } from '../middleware/errorHandler';
import { notFoundHandler } from '../middleware/notFoundHandler';

export interface Controllers {
  users: UserController;
  projects: ProjectController;
  tasks: TaskController;
}

export function createApp(controllers: Controllers): Express {
  const app = express();
  app.use(express.json());

  app.post('/users', controllers.users.create);
  app.post('/projects', controllers.projects.create);
  app.post('/projects/:projectId/tasks', controllers.tasks.create);
  app.get('/projects/:projectId/tasks', controllers.tasks.listByProject);
  app.put('/tasks/:taskId/assignee', controllers.tasks.assign);
  app.post('/tasks/:taskId/complete', controllers.tasks.complete);

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

